import"./chunk-7CGTOI24.js";var e={slug:"cara-de-barro-terror-dc",title:"Cara-de-Barro: a DC aposta no terror com roteiro de Mike Flanagan",dek:"O vil\xE3o do Batman ganha filme pr\xF3prio, com dire\xE7\xE3o de James Watkins e classifica\xE7\xE3o 18 anos. Estreia nesta quinta (22). Saiba o que esperar.",section:"filmes",kind:"noticia",tags:["DC","Terror","Estreias"],date:"2026-10-21",hero:{ref:"movie:1400940",pick:0,alt:"Tom Rhys Harries em cena de Cara-de-Barro"},body:[{p:"Um dos vil\xF5es mais tr\xE1gicos da galeria do Batman chega aos cinemas brasileiros nesta quinta-feira (22). *Cara-de-Barro* \xE9 produzido pela DC Studios e n\xE3o esconde o g\xEAnero: \xE9 um filme de terror, com classifica\xE7\xE3o indicativa de 18 anos."},{ficha:"movie:1400940"},{h2:"Quem \xE9 Matt Hagen"},{p:"Segundo a sinopse oficial, Matt Hagen, vivido por Tom Rhys Harries, sai das ruas de Gotham para o estrelato em Hollywood, at\xE9 que um chef\xE3o do crime local o deixa desfigurado. Abandonado por todos, ele recorre a um tratamento de ponta que devolve sua apar\xEAncia, mas altera sua percep\xE7\xE3o da realidade e o empurra para uma espiral de obsess\xE3o e vingan\xE7a."},{p:"Nos quadrinhos, o nome Cara-de-Barro j\xE1 passou por v\xE1rios personagens. O primeiro foi Basil Karlo, um ator de filmes de terror que estreou em 1940. Matt Hagen, o ca\xE7ador de tesouros que ganha a capacidade de moldar o pr\xF3prio corpo, chegou em 1961 e ficou marcado pela ideia de um homem que pode ser qualquer pessoa, menos ele mesmo. O filme parece misturar as duas origens, ao fazer de Hagen um astro de Hollywood."},{p:"Naomi Ackie interpreta Caitlyn Corr, e Eddie Marsan, Max Minghella e David Dencik completam o elenco principal, de acordo com o TMDB."},{img:"movie:1400940",pick:1,caption:"Cara-de-Barro tem 109 minutos. Imagem de divulga\xE7\xE3o."},{h2:"A dupla por tr\xE1s das c\xE2meras"},{p:"A dire\xE7\xE3o \xE9 de James Watkins, que tem no curr\xEDculo *A Mulher de Preto* e a refilmagem americana de *N\xE3o Fale o Mal*. O roteiro \xE9 de Mike Flanagan, nome de s\xE9ries como *A Maldi\xE7\xE3o da Resid\xEAncia Hill* e *Missa da Meia-Noite*. Juntos, s\xE3o uma combina\xE7\xE3o que promete mais horror corporal e drama do que pancadaria."},{quote:"Cara-de-Barro sempre foi um vil\xE3o sobre identidade e apar\xEAncia. Faz sentido que algu\xE9m finalmente o trate como personagem de terror."},{h2:"Terror de verdade em um filme de super-her\xF3i"},{p:"A classifica\xE7\xE3o de 18 anos no Brasil diz muito. Filmes de personagens de quadrinhos costumam mirar a faixa de 12 a 14 anos para alcan\xE7ar o maior p\xFAblico poss\xEDvel. *Cara-de-Barro* vai na dire\xE7\xE3o contr\xE1ria e aposta em um nicho que vem crescendo: quem gosta de terror e acompanha esses universos, mas quer algo diferente das batalhas de sempre."},{h2:"Precisa conhecer o Batman?"},{p:"N\xE3o. Pela sinopse, o filme \xE9 centrado em Hagen e funciona como hist\xF3ria de origem. Gotham \xE9 cen\xE1rio, n\xE3o pr\xE9-requisito."},{box:"Mat\xE9ria escrita antes da estreia. A reda\xE7\xE3o ainda n\xE3o assistiu ao filme.",title:"Antes da sess\xE3o"},{p:"Se o g\xEAnero \xE9 a sua praia, veja as [estreias de terror de novembro](/artigo/estreias-de-novembro-nos-cinemas)."}]};var o={source:"TMDB + IGDB",updatedAt:"2026-11-10",calendar:[],games:{},movies:{1400940:{id:1400940,title:"Cara-de-Barro",original:"Clayface",overview:"A ascens\xE3o mete\xF3rica de Matt Hagen de garoto das ruas de Gotham a astro de Hollywood \xE9 tragicamente interrompida quando as a\xE7\xF5es de um chef\xE3o do crime local o deixam terrivelmente desfigurado. Abandonado por sua equipe e sem nada, Matt busca um tratamento de ponta que, milagrosamente, o devolve \xE0 sua antiga forma... mas que tamb\xE9m afeta, de maneira inesperada, sua percep\xE7\xE3o da realidade, lan\xE7ando-o em uma espiral destrutiva de obsess\xE3o e vingan\xE7a.",poster:"/dqvHs2YXks989ScXvsngbqAeBHX.jpg",backdrops:["/uL4cIrNi2uaUnWIOQQ28EVnkETG.jpg","/VnT9D7NogVWrmN2UuT30exIYPh.jpg","/xSDoxv4pHvs4xZjvTb0Iqg1A6ro.jpg","/kVtOcoUJ68chBD2tmERkdWz7lK5.jpg","/3YHeDqu5MCyqan4ptiY8q726vzU.jpg"],runtime:109,genres:["Terror","Thriller","Fic\xE7\xE3o cient\xEDfica"],cert:"18",release:"2026-10-22",world:"2026-10-19",directors:["James Watkins"],writers:["Mike Flanagan"],cast:[{name:"Tom Rhys Harries",role:"Matt Hagen / Clayface"},{name:"Naomi Ackie",role:"Caitlyn Corr"},{name:"Eddie Marsan",role:"Frank Fitzpatrick"},{name:"Max Minghella",role:"John Borrelli"},{name:"David Dencik",role:"Markos Szabo"},{name:"Francesca Corney",role:"Rosie"}],studios:["DC Studios","Domain Entertainment"],country:"US"}},tv:{}};export{o as media,e as post};
